import asyncio
import functools
import time
from dataclasses import dataclass


@dataclass
class Job:
    name: str
    func: object
    arg: object


@dataclass
class Ok:
    job: str
    value: object
    seconds: float


@dataclass
class Failed:
    job: str
    error: str
    seconds: float


def timed(func):
    @functools.wraps(func)
    async def wrapper(*args, **kwargs):
        start = time.perf_counter()
        value = await func(*args, **kwargs)
        return value, time.perf_counter() - start
    return wrapper


async def run_jobs(jobs, limit=3):
    gate = asyncio.Semaphore(limit)

    async def run_one(job):
        async with gate:
            start = time.perf_counter()
            try:
                value, seconds = await timed(job.func)(job.arg)
                return Ok(job.name, value, seconds)
            except Exception as e:
                return Failed(job.name, f"{type(e).__name__}: {e}", time.perf_counter() - start)

    return list(await asyncio.gather(*(run_one(job) for job in jobs)))


def report(results):
    lines = []
    ok = failed = 0
    for result in results:
        match result:
            case Ok(job, value, _):
                lines.append(f"{job}: ok ({value})")
                ok += 1
            case Failed(job, error, _):
                lines.append(f"{job}: failed ({error})")
                failed += 1
    lines.append(f"{ok} ok, {failed} failed")
    return "".join(line + "\n" for line in lines)
